package de.kopfzentrum.gam.laboratory;
import jakarta.annotation.PostConstruct;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.*;import java.time.*;import java.util.*;
@Repository public class LaboratoryOrderRepository{private final JdbcTemplate jdbc;public LaboratoryOrderRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}@PostConstruct void init(){jdbc.execute("CREATE TABLE IF NOT EXISTS laboratory_order (id BIGINT AUTO_INCREMENT PRIMARY KEY,patient_number VARCHAR(80),patient_name VARCHAR(255) NOT NULL,requested_by VARCHAR(255),external_laboratory VARCHAR(255),examinations TEXT,specimen_material VARCHAR(120),priority VARCHAR(40) NOT NULL DEFAULT 'NORMAL',status VARCHAR(60) NOT NULL DEFAULT 'ANGELEGT',due_date DATE,collected_at DATETIME,collected_by VARCHAR(255),specimen_id VARCHAR(120),sent_at DATETIME,result_received_at DATETIME,result_summary TEXT,reviewed_by VARCHAR(255),reviewed_at DATETIME,patient_information TEXT,note TEXT,created_by VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by VARCHAR(255),updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_laboratory_status(status),INDEX idx_laboratory_due(due_date),INDEX idx_laboratory_patient(patient_name))");}
public List<LaboratoryOrder> list(String q,String status){StringBuilder s=new StringBuilder("SELECT * FROM laboratory_order WHERE 1=1");List<Object>a=new ArrayList<>();if(q!=null&&!q.isBlank()){s.append(" AND (patient_name LIKE ? OR patient_number LIKE ? OR examinations LIKE ? OR specimen_id LIKE ? OR external_laboratory LIKE ?)");for(int i=0;i<5;i++)a.add("%"+q.trim()+"%");}if(status!=null&&!status.isBlank()&&!"all".equalsIgnoreCase(status)){s.append(" AND status=?");a.add(status);}s.append(" ORDER BY CASE WHEN due_date IS NULL THEN 1 ELSE 0 END,due_date,id DESC");return jdbc.query(s.toString(),this::map,a.toArray());}
public LaboratoryOrder get(long id){return jdbc.query("SELECT * FROM laboratory_order WHERE id=?",this::map,id).stream().findFirst().orElseThrow(()->new IllegalArgumentException("Laborauftrag nicht gefunden."));}
public LaboratoryOrder create(LaboratoryOrderRequest r,String u){validate(r);jdbc.update("INSERT INTO laboratory_order(patient_number,patient_name,requested_by,external_laboratory,examinations,specimen_material,priority,status,due_date,collected_at,collected_by,specimen_id,sent_at,result_received_at,result_summary,reviewed_by,reviewed_at,patient_information,note,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",c(r.patientNumber()),c(r.patientName()),c(r.requestedBy()),c(r.externalLaboratory()),c(r.examinations()),c(r.specimenMaterial()),v(r.priority(),"NORMAL"),status(r.status()),date(r.dueDate()),dt(r.collectedAt()),c(r.collectedBy()),c(r.specimenId()),dt(r.sentAt()),dt(r.resultReceivedAt()),c(r.resultSummary()),c(r.reviewedBy()),dt(r.reviewedAt()),c(r.patientInformation()),c(r.note()),u,u);return get(Objects.requireNonNull(jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class)));}
public LaboratoryOrder update(long id,LaboratoryOrderRequest r,String u){get(id);validate(r);jdbc.update("UPDATE laboratory_order SET patient_number=?,patient_name=?,requested_by=?,external_laboratory=?,examinations=?,specimen_material=?,priority=?,status=?,due_date=?,collected_at=?,collected_by=?,specimen_id=?,sent_at=?,result_received_at=?,result_summary=?,reviewed_by=?,reviewed_at=?,patient_information=?,note=?,updated_by=? WHERE id=?",c(r.patientNumber()),c(r.patientName()),c(r.requestedBy()),c(r.externalLaboratory()),c(r.examinations()),c(r.specimenMaterial()),v(r.priority(),"NORMAL"),status(r.status()),date(r.dueDate()),dt(r.collectedAt()),c(r.collectedBy()),c(r.specimenId()),dt(r.sentAt()),dt(r.resultReceivedAt()),c(r.resultSummary()),c(r.reviewedBy()),dt(r.reviewedAt()),c(r.patientInformation()),c(r.note()),u,id);return get(id);}public void delete(long id){jdbc.update("DELETE FROM laboratory_order WHERE id=?",id);}
private void validate(LaboratoryOrderRequest r){if(c(r.patientName()).isBlank())throw new IllegalArgumentException("Patient fehlt.");if(c(r.examinations()).isBlank())throw new IllegalArgumentException("Mindestens eine Untersuchung fehlt.");String st=status(r.status());if(List.of("PROBE_ENTNOMMEN","VERSANDT","BEFUND_EINGEGANGEN","AERZTLICH_GEPRUEFT","PATIENT_INFORMIERT","ABGESCHLOSSEN").contains(st)&&c(r.specimenMaterial()).isBlank())throw new IllegalArgumentException("Probenmaterial fehlt.");if(List.of("AERZTLICH_GEPRUEFT","PATIENT_INFORMIERT","ABGESCHLOSSEN").contains(st)&&c(r.reviewedBy()).isBlank())throw new IllegalArgumentException("Ärztliche Prüfung muss dokumentiert werden.");if("ABGESCHLOSSEN".equals(st)&&c(r.patientInformation()).isBlank())throw new IllegalArgumentException("Patienteninformation muss vor Abschluss dokumentiert werden.");}
private LaboratoryOrder map(ResultSet x,int n)throws SQLException{return new LaboratoryOrder(x.getLong("id"),x.getString("patient_number"),x.getString("patient_name"),x.getString("requested_by"),x.getString("external_laboratory"),x.getString("examinations"),x.getString("specimen_material"),x.getString("priority"),x.getString("status"),ld(x,"due_date"),ldt(x,"collected_at"),x.getString("collected_by"),x.getString("specimen_id"),ldt(x,"sent_at"),ldt(x,"result_received_at"),x.getString("result_summary"),x.getString("reviewed_by"),ldt(x,"reviewed_at"),x.getString("patient_information"),x.getString("note"),x.getString("created_by"),ldt(x,"created_at"),x.getString("updated_by"),ldt(x,"updated_at"));}
private static String c(String s){return s==null?"":s.trim();}private static String v(String s,String d){return c(s).isBlank()?d:c(s);}private static String status(String s){String z=v(s,"ANGELEGT").toUpperCase().replace(' ','_').replace("Ä","AE");return Set.of("ANGELEGT","ANGEFORDERT","PATIENT_VORBEREITET","PROBE_ENTNOMMEN","VERSANDT","BEFUND_EINGEGANGEN","AERZTLICH_GEPRUEFT","PATIENT_INFORMIERT","ABGESCHLOSSEN","NACHENTNAHME_ERFORDERLICH","ABGEBROCHEN").contains(z)?z:"ANGELEGT";}private static LocalDate date(String s){try{return c(s).isBlank()?null:LocalDate.parse(s);}catch(Exception e){throw new IllegalArgumentException("Ungültiges Datum.");}}private static LocalDateTime dt(String s){try{return c(s).isBlank()?null:LocalDateTime.parse(s);}catch(Exception e){throw new IllegalArgumentException("Ungültiger Zeitpunkt.");}}private static LocalDate ld(ResultSet r,String c)throws SQLException{java.sql.Date d=r.getDate(c);return d==null?null:d.toLocalDate();}private static LocalDateTime ldt(ResultSet r,String c)throws SQLException{Timestamp t=r.getTimestamp(c);return t==null?null:t.toLocalDateTime();}}
